// ENG-2360 docs screenshots: relation type menu empty state, + flyout, Add existing picker, Create new flow (GIF frames).
import fs from "node:fs";
import { prepare, clickButton, observe } from "./base.mjs";

const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const OUT = new URL("./shots/", import.meta.url).pathname;
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const P = (ctx) => `app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}]`;
const DIALOG = `[...document.querySelectorAll(".modal-container")].find((m) => m.querySelector(".modal-title")?.textContent.trim() === "Add relation type")`;

const dialog = (ctx) =>
  ctx.client.evaluate(`
    const m = ${DIALOG};
    if (!m) return { open: false };
    const inputs = [...m.querySelectorAll("input[type=text]")];
    return {
      open: true,
      placeholders: inputs.map((i) => i.placeholder),
      values: inputs.map((i) => i.value),
      invalid: inputs.map((i) => i.classList.contains("input-error")),
      error: m.querySelector(".text-error")?.textContent.trim() ?? null,
      color: m.querySelector(".relative.min-w-32 > button")?.textContent.replace(/[▲▼]/g, "").trim() ?? null,
      buttons: [...m.querySelectorAll(".modal-button-container button")].map((b) => b.textContent.trim()),
      focused: document.activeElement?.placeholder ?? document.activeElement?.tagName,
    };`);

const centerOf = async (ctx, js) => {
  const p = await ctx.client.evaluate(`const el = (() => { ${js} })(); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
  if (!p) throw new Error(`element not found: ${js}`);
  return p;
};
const clickAt = async (client, { x, y }) => {
  const m = (type, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  await m("mouseMoved", { button: "none" });
  await m("mousePressed", { buttons: 1 });
  await m("mouseReleased");
  await sleep(250);
};
const clickEl = async (ctx, js) => clickAt(ctx.client, await centerOf(ctx, js));
const clickInput = (ctx, i) => clickEl(ctx, `return ${DIALOG}?.querySelectorAll("input[type=text]")[${i}];`);
const clickDialogButton = (ctx, text) =>
  clickEl(ctx, `return [...(${DIALOG}?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(text)});`);
const colorOption = (ctx, name) =>
  `return [...(${DIALOG}?.querySelectorAll(".relative.min-w-32 > div button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(name)});`;

const openDialog = async (ctx, where) => {
  await clickButton(ctx, "Create new", where);
  await ctx.client.waitFor(`!!${DIALOG}`, { label: "Add relation type dialog" });
  await sleep(200);
};

// Types into the focused label input, then the complement; picks a colour when given.
const fillDialog = async (ctx, { label, complement, color }) => {
  if (label) {
    await clickInput(ctx, 0);
    await ctx.client.typeText(label);
  }
  if (complement) {
    await clickInput(ctx, 1);
    await ctx.client.typeText(complement);
  }
  if (color) {
    await clickEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`);
    await clickEl(ctx, colorOption(ctx, color));
  }
};

const diskSettings = (ctx) =>
  ctx.client.evaluate(`return app.vault.adapter.read(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")}).then((t) => { const d = JSON.parse(t); return { relationTypes: d.relationTypes, discourseRelations: d.discourseRelations }; });`);

const pair = (ctx, from, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; return { s: ed.getShape(${ctx.json(from)}).props.nodeTypeId, t: ed.getShape(${ctx.json(to)}).props.nodeTypeId };`);

const snapshot = async (ctx) => ({
  relationsJson: await ctx.client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json"));`),
  settings: await ctx.client.evaluate(`const s = ${P(ctx)}.settings; return JSON.stringify({ relationTypes: s.relationTypes, discourseRelations: s.discourseRelations });`),
});
const restore = async (ctx, state) => {
  await ctx.client.clearModals?.();
  await ctx.client.evaluate(`const ed = window.__dgEd; ed?.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id)); return true;`);
  if (!state) return;
  await ctx.client.evaluate(`const p = ${P(ctx)}; Object.assign(p.settings, JSON.parse(${ctx.json(state.settings)})); return p.saveSettings().then(() => true);`);
  await ctx.client.evaluate(`return app.vault.modify(app.vault.getAbstractFileByPath("relations.json"), ${ctx.json(state.relationsJson)}).then(() => true);`);
};


// Tidy fixture, clean in-memory settings (restored in teardown), hide Obsidian notices.
const docsPrepare = async (ctx) => {
  await ctx.client.evaluate(`app.workspace.leftSplit.collapse(); app.workspace.rightSplit.collapse(); return true;`);
  await prepare(ctx);
  await ctx.client.evaluate(`const st = ${P(ctx)}.settings;
    const keep = new Set(["supports", "opposes", "informs", "derived from"]);
    st.relationTypes = st.relationTypes.filter((r) => keep.has(r.label));
    const ids = new Set(st.relationTypes.map((r) => r.id));
    const q = ${ctx.json("node_vqZxAvvuf-AN9E5Y4kH-F")}, c = ${ctx.json("node_bqu6_78DrVvuDnqmc6QzS")};
    st.discourseRelations = st.discourseRelations.filter((r) => ids.has(r.relationshipTypeId) &&
      !((r.sourceId === q && r.destinationId === c) || (r.sourceId === c && r.destinationId === q)));
    const ed = window.__dgEd;
    ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type !== "discourse-node").map((s) => s.id));
    ed.updateShapes([
      { id: ${ctx.json(C)}, type: "discourse-node", x: 0, y: 0, rotation: 0 },
      { id: ${ctx.json(Q)}, type: "discourse-node", x: 760, y: 0, rotation: 0 },
      { id: ${ctx.json(E)}, type: "discourse-node", x: 0, y: 360, rotation: 0 },
    ]);
    ed.selectNone();
    const z = 0.8; ed.setCamera({ x: 70 / z, y: 90 / z, z }, { immediate: true });
    document.querySelectorAll(".notice").forEach((n) => n.remove());
    return true;`);
  await sleep(500);
};

const hideNotices = (ctx) => ctx.client.evaluate(`document.querySelectorAll(".notice").forEach((n) => n.remove()); return true;`);

// Canvas container rect (CSS px).
const clipRect = (ctx) =>
  ctx.client.evaluate(`const ed = window.__dgEd; const r = ed.getContainer().getBoundingClientRect();
    return { x: r.left, y: r.top, width: r.width, height: r.height };`);

// Clip to the canvas container (CSS px); captured at device scale.
const shot = async (ctx, name) => {
  await hideNotices(ctx);
  const r = await clipRect(ctx);
  const { data } = await ctx.client.send("Page.captureScreenshot", { format: "png", clip: { ...r, scale: 1 } });
  fs.writeFileSync(OUT + name, Buffer.from(data, "base64"));
  return name;
};

// Drag from the dot of `from` nearest `to`, capturing a frame every few steps when `frames` is given.
const drag = async (ctx, from, to, frames) => {
  const { client, json } = ctx;
  const m = (type, x, y, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  const c0 = await client.evaluate(`const ed = window.__dgEd; const b = ed.getShapePageBounds(${json(from)}); return ed.pageToScreen({ x: b.midX, y: b.midY });`);
  await m("mouseMoved", c0.x, c0.y, { button: "none" });
  await m("mousePressed", c0.x, c0.y, { buttons: 1 });
  await m("mouseReleased", c0.x, c0.y);
  await sleep(400);
  if (frames) await frames.add("select", 2);
  const { start, target } = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 }; });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target };`);
  if (!start) throw new Error("no drag dots");
  await m("mouseMoved", start.x, start.y, { button: "none" });
  await m("mousePressed", start.x, start.y, { buttons: 1 });
// WebSocket without a dependency: Node 22+ global, else `ws` from the repo's pnpm store.
import { createRequire } from "node:module";
import { existsSync, readdirSync } from "node:fs";
import path from "node:path";

const fromPnpmStore = (startDir) => {
  for (let dir = path.resolve(startDir); ; dir = path.dirname(dir)) {
    const store = path.join(dir, "node_modules", ".pnpm");
    if (existsSync(store)) {
      const match = readdirSync(store).filter((e) => e.startsWith("ws@")).sort().at(-1);
      const candidate = match && path.join(store, match, "node_modules", "ws", "index.js");
      if (candidate && existsSync(candidate)) return candidate;
    }
    if (path.dirname(dir) === dir) return null;
  }
};

export const resolveWebSocket = async ({ from = process.cwd() } = {}) => {
  if (typeof globalThis.WebSocket === "function") return globalThis.WebSocket;
  try {
    return createRequire(path.join(from, "noop.js"))("ws");
  } catch {
    const storePath = fromPnpmStore(from);
    if (storePath) {
      const loaded = await import(`file://${storePath}`);
      return loaded.default ?? loaded.WebSocket;
    }
  }
  throw new Error("No WebSocket: use Node 22+ or run inside the monorepo after pnpm install.");
};
---
name: reference-cdp-verify-harness-contract
description: "dg-obsidian-cdp-verify scenario contract: evaluate() needs an explicit top-level return, waitFor() only succeeds on literal true, key() takes an options object"
metadata:
  node_type: memory
  type: reference
  originSessionId: e9bb47d2-c844-4381-8d17-490ed7677aa5
  modified: 2026-09-30T03:55:15.916Z
---

Three contract details in `dg-obsidian-cdp-verify`'s scenario API. Getting them wrong fails every
scenario with the *same* error, which reads like a product bug rather than a harness mistake — on
ENG-2228 all five scenarios failed identically at "timeout waiting for text shape in store" when
the real cause was the driver calls.

- **`evaluate(expr)` wraps the body in a plain function and only adds a `return` when the string
  contains no `return` at all** (`driver.mjs`: `/\breturn\b/.test(expression) ? expression : "return (…)"`).
  So a self-invoking `(() => { … return x; })()` matches the regex, is treated as a *body*, and
  silently yields `undefined`. Always write an explicit top-level `return …;`.
- **`waitFor(expr)` resolves only when the expression evaluates to literal `true`.** It returns
  `undefined`, never the value. Use it for the condition, then a separate `evaluate` to read data —
  `await waitFor("return shapes.length > 0;")` then `await evaluate("return shapes[0].id;")`.
- **`key()` takes an options object, not a string.** `client.key("t")` spreads a string into the CDP
  params and does nothing; use
  `client.key({ text: "t", key: "t", code: "KeyT", windowsVirtualKeyCode: 84, nativeVirtualKeyCode: 84 })`.
  `typeText` and `pressEscape` are the string-friendly wrappers.

Other operational notes:

- Slots come from `OBSIDIAN_VERIFY_VAULTS` in `<worktree>/apps/obsidian/.env`. A worktree created
  before that variable existed won't have it — copy the line from the main checkout's `.env`
  (it is gitignored, so it is not inherited). `doctor.mjs --slot N` tells you which vault resolves.
- The build mirrors to the slot's vault, which may not be the vault you have open. Check the
  `mirrored to …` line before assuming a stale build; see
  [[reference-obsidian-contested-vault-plugin-dir]].
- Flaky single failures are real here — a scenario that passed on the previous run with identical
  code usually passes again. Rerun before diagnosing, per the skill's own gotcha table.

Raw CDP driving without the harness: [[reference-obsidian-cdp-driving]]. Note that programmatic
`store.put` fires no tldraw store listeners, so it never triggers the canvas autosave —
[[reference-tldraw-store-put-no-listener]].

