type ColorPickerProps = {
  value: string;
  onChange: (color: TldrawColorName) => void;
  disabled?: boolean;
};

export const ColorPicker = ({
  value,
  onChange,
  disabled,
}: ColorPickerProps) => {
  const [isOpen, setIsOpen] = useState(false);
  const dropdownRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const handleClickOutside = (event: MouseEvent) => {
      if (
        dropdownRef.current &&
        !dropdownRef.current.contains(event.target as Node)
      ) {
        setIsOpen(false);
      }
    };

    if (isOpen) {
      document.addEventListener("mousedown", handleClickOutside);
      return () => {
        document.removeEventListener("mousedown", handleClickOutside);
      };
    }
  }, [isOpen]);

  const currentColor = value as TldrawColorName;
  const bgColor = COLOR_PALETTE[currentColor] ?? COLOR_PALETTE.black;
  const textColor = getContrastColor(bgColor ?? DEFAULT_TLDRAW_COLOR);

  return (
    <div ref={dropdownRef} className="relative min-w-32">
      <button
        type="button"
        onClick={() => !disabled && setIsOpen(!isOpen)}
        className="flex w-full items-center justify-between rounded border px-3 py-2 text-left"
        style={{ backgroundColor: bgColor, color: textColor }}
        disabled={disabled}
      >
        <span className="flex items-center gap-2">
          <span
            className="inline-block h-3 w-3 rounded-full border-2 border-solid"
            style={{ backgroundColor: bgColor, border: `${textColor}` }}
          />
          {TLDRAW_COLOR_LABELS[currentColor]}
        </span>
        <span className="text-sm">{isOpen ? "▲" : "▼"}</span>
      </button>

      {isOpen && (
        <div className="absolute z-50 mt-1 max-h-40 w-full overflow-y-auto">
          {TLDRAW_COLOR_NAMES.map((colorName) => {
            const bgColor = COLOR_PALETTE[colorName] ?? COLOR_PALETTE.black;
            return (
              <button
                key={colorName}
                type="button"
                onClick={() => {
                  onChange(colorName);
                  setIsOpen(false);
                }}
                className="flex w-full flex-row justify-start gap-2 rounded-none px-3 py-2"
              >
                <span
                  className="inline-block h-3 w-3 rounded-full"
                  style={{ backgroundColor: bgColor }}
                />
                {TLDRAW_COLOR_LABELS[colorName]}
              </button>
            );
          })}
        </div>
      )}
    </div>
  );
};

const RelationshipTypeSettings = () => {
  const plugin = usePlugin();
  const [relationTypes, setRelationTypes] = useState<DiscourseRelationType[]>(
    () => plugin.settings.relationTypes ?? [],
  );
  const [errors, setErrors] = useState<Record<number, string>>({});
  // Ref to always have the latest state for onBlur handlers
  // Updated in handleRelationTypeChange, not on render, to avoid stale reads
  const relationTypesRef = useRef(relationTypes);

  type EditableFieldKey = keyof Omit<
    DiscourseRelationType,
    "id" | "modified" | "created" | "importedFromRid" | "status"
  >;

  const saveSettings = (updatedRelationTypes: DiscourseRelationType[]) => {
    const newErrors = getRelationTypeErrors(updatedRelationTypes);
    const completeTypes = updatedRelationTypes.filter(isCompleteRelationType);

    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;

    // Only persist complete local types + all imported types
    const importedTypes = updatedRelationTypes.filter(
      (rt) => rt.importedFromRid,
    );
    plugin.settings.relationTypes = [
      ...completeTypes.filter((rt) => !rt.importedFromRid),
      ...importedTypes,
    ];
    void plugin.saveSettings();
  };

  const handleRelationTypeChange = (
    index: number,
    field: EditableFieldKey,
    value: string,
  ): void => {
    const now = new Date().getTime();
    const updatedRelationTypes = [...relationTypes];
    if (!updatedRelationTypes[index]) {
      const newId = generateUid("rel");
      updatedRelationTypes[index] = {
        id: newId,
        label: "",
        complement: "",
        color: DEFAULT_TLDRAW_COLOR,
        created: now,
        modified: now,
      };
    }
    const updated = {
      ...updatedRelationTypes[index],
      modified: now,
      ...(field === "color"
        ? { color: value as TldrawColorName }
        : { [field]: value }),
    };
    updatedRelationTypes[index] = updated;
    setRelationTypes(updatedRelationTypes);
    relationTypesRef.current = updatedRelationTypes;
    if (field === "color") {
      // Color is a discrete input — save immediately
      saveSettings(updatedRelationTypes);
    }
  };

  const handleAddRelationType = (): void => {
    const newId = generateUid("rel");
    const now = new Date().getTime();

    const updatedRelationTypes = [
      ...relationTypes,
      {
        id: newId,
        label: "",
        complement: "",
        color: DEFAULT_TLDRAW_COLOR,
        created: now,
        modified: now,
      },
    ];
    setRelationTypes(updatedRelationTypes);
  };

  const confirmDeleteRelationType = (index: number): void => {
    const relationType = relationTypes[index] || {
      label: "Unnamed",
      complement: "",
      color: DEFAULT_TLDRAW_COLOR,
    };
    const modal = new ConfirmationModal(plugin.app, {
      title: "Delete relation type",
      message: `Are you sure you want to delete the relation type "${relationType.label}"?`,
      onConfirm: () => {
        void handleDeleteRelationType(index);
      },
    });
    modal.open();
  };

  const handleDeleteRelationType = async (index: number): Promise<void> => {
    const isUsed = plugin.settings.discourseRelations?.some(
      (rel) => rel.relationshipTypeId === relationTypes[index]?.id,
    );

    if (isUsed) {
      new Notice(
        "Cannot delete this relation type as it is used in one or more relations.",
      );
      return;
    }

    const updatedRelationTypes = relationTypes.filter((_, i) => i !== index);
    setRelationTypes(updatedRelationTypes);
    plugin.settings.relationTypes = updatedRelationTypes;
    await plugin.saveSettings();
    new Notice("Relation type deleted successfully");
  };

  const handleAcceptRelationType = async (index: number): Promise<void> => {
    const updatedRelationTypes = [...relationTypes];
    const relType = updatedRelationTypes[index];
    if (!relType) return;
    updatedRelationTypes[index] = { ...relType, status: "accepted" };
    setRelationTypes(updatedRelationTypes);
    plugin.settings.relationTypes = updatedRelationTypes;
    await plugin.saveSettings();
  };

  const localRelationTypes = relationTypes.filter(
    (relationType) => !relationType.importedFromRid,
  );
  const importedRelationTypes = relationTypes.filter(
    (relationType) => relationType.importedFromRid,
  );

  const renderRelationTypeItem = (
    relationType: DiscourseRelationType,
    index: number,
  ) => {
    const importInfo = getImportInfo(relationType.importedFromRid);
    const isImported = importInfo.isImported;
    const isProvisional = isProvisionalSchema(relationType);
    const spaceName = importInfo.spaceUri
      ? formatImportSource(importInfo.spaceUri, plugin.settings.spaceNames)
      : "imported space";

    const error = errors[index];

    return (
      <div key={index} className="setting-item">
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <div className="flex flex-wrap items-center gap-2">
            <input
              type="text"
              placeholder="Label (e.g., supports)"
              value={relationType.label}
              onChange={(e) =>
                handleRelationTypeChange(index, "label", e.target.value)
              }
              onBlur={() => saveSettings(relationTypesRef.current)}
              className={`min-w-32 flex-1 ${error ? "input-error" : ""}`}
              disabled={isImported}
            />
            <input
              type="text"
              placeholder="Complement (e.g., is supported by)"
              value={relationType.complement}
              onChange={(e) =>
                handleRelationTypeChange(index, "complement", e.target.value)
              }
              onBlur={() => saveSettings(relationTypesRef.current)}
              className={`min-w-48 flex-[2] ${error ? "input-error" : ""}`}
              disabled={isImported}
            />
            <ColorPicker
              value={relationType.color}
              onChange={(color) =>
                handleRelationTypeChange(index, "color", color)
              }
              disabled={isImported}
            />
            <div className="flex shrink-0 gap-2">
              {isImported && isProvisional && (
                <button
                  onClick={() => void handleAcceptRelationType(index)}
                  className="p-2"
                  title={`Accept this relation type from ${spaceName} to create relations of this type`}
                >
                  Accept
                </button>
              )}
              <button
                onClick={() => confirmDeleteRelationType(index)}
                className="mod-warning p-2"
              >
                Delete
              </button>
            </div>
          </div>
          {error && <div className="text-error text-xs">{error}</div>}
          {isImported && (
            <ImportedSchemaMeta
              isProvisional={isProvisional}
              spaceUri={importInfo.spaceUri}
              authorId={relationType.authorId}
            />
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="discourse-relation-types">
      {localRelationTypes.length > 0 && (
        <div>
          <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
            Local
          </h4>
          {localRelationTypes.map((relationType) => {
            const index = relationTypes.indexOf(relationType);
            return renderRelationTypeItem(relationType, index);
          })}
        </div>
      )}

      {importedRelationTypes.length > 0 && (
        <div className="border-modifier-border mt-6 border-t pt-4">
          <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
            Imported
          </h4>
          {importedRelationTypes.map((relationType) => {
            const index = relationTypes.indexOf(relationType);
            return renderRelationTypeItem(relationType, index);
          })}
        </div>
      )}

      <div className="mt-4 flex gap-2">
        <button onClick={handleAddRelationType} className="p-2">
          Add relation type
        </button>
      </div>
    </div>
  );
};

export default RelationshipTypeSettings;
import { useState } from "react";
import { DiscourseRelation, DiscourseRelationType } from "~/types";
import { Notice } from "obsidian";
import { usePlugin } from "./PluginContext";
import { ConfirmationModal } from "./ConfirmationModal";
import {
  getNodeTypeById,
  getImportInfo,
  formatImportSource,
  isAcceptedSchema,
  isProvisionalSchema,
} from "~/utils/typeUtils";
import generateUid from "~/utils/generateUid";
import ImportedSchemaMeta from "./ImportedSchemaMeta";

const RelationshipSettings = () => {
  const plugin = usePlugin();
  const [discourseRelations, setDiscourseRelations] = useState<
    DiscourseRelation[]
  >(() => plugin.settings.discourseRelations ?? []);
  const [errors, setErrors] = useState<Record<number, string>>({});

  const findRelationTypeById = (
    id: string,
  ): DiscourseRelationType | undefined => {
    return plugin.settings.relationTypes.find((relType) => relType.id === id);
  };

  type EditableFieldKey = keyof Omit<
    DiscourseRelation,
    "id" | "modified" | "created" | "importedFromRid" | "status"
  >;

  const saveSettings = (relations: DiscourseRelation[]): void => {
    const newErrors: Record<number, string> = {};
    const completeRelations = relations.filter(
      (r) => r.relationshipTypeId && r.sourceId && r.destinationId,
    );

    // Check for duplicates among complete relations
    const seenKeys = new Map<string, number>();
    for (const r of completeRelations) {
      const idx = relations.indexOf(r);
      const key = `${r.relationshipTypeId}-${r.sourceId}-${r.destinationId}`;
      const prev = seenKeys.get(key);
      if (prev !== undefined) {
        newErrors[idx] = "Duplicate relation";
        if (!newErrors[prev]) newErrors[prev] = "Duplicate relation";
      }
      seenKeys.set(key, idx);
    }

    setErrors(newErrors);
    if (Object.keys(newErrors).length > 0) return;

    // Persist complete local relations + all imported relations
    const importedRelations = relations.filter((r) => r.importedFromRid);
    plugin.settings.discourseRelations = [
      ...completeRelations.filter((r) => !r.importedFromRid),
      ...importedRelations,
    ];
    void plugin.saveSettings();
  };

  const handleRelationChange = (
    index: number,
    field: EditableFieldKey,
    value: string,
  ): void => {
    const updatedRelations = [...discourseRelations];

    const now = new Date().getTime();
    if (!updatedRelations[index]) {
      const newId = generateUid("rel3");
      updatedRelations[index] = {
        id: newId,
        sourceId: "",
        destinationId: "",
        relationshipTypeId: "",
        created: now,
        modified: now,
      };
    }

    updatedRelations[index] = {
      ...updatedRelations[index],
      [field]: value,
      modified: now,
    };
    setDiscourseRelations(updatedRelations);
    saveSettings(updatedRelations);
  };

  const handleAddRelation = (): void => {
    const newId = generateUid("rel3");
    const now = new Date().getTime();
    const updatedRelations = [
      ...discourseRelations,
      {
        id: newId,
        sourceId: "",
        destinationId: "",
        relationshipTypeId: "",
        created: now,
        modified: now,
      },
    ];
    setDiscourseRelations(updatedRelations);
  };

  const confirmDeleteRelation = (index: number): void => {
    const relation = discourseRelations[index] || {
      sourceId: "",
      destinationId: "",
      relationshipTypeId: "",
    };
    let message = "Are you sure you want to delete this relation?";

    // If the relation has source and target nodes, provide more context
    if (
      relation.sourceId &&
      relation.destinationId &&
      relation.relationshipTypeId
    ) {
      const sourceNode = getNodeTypeById(plugin, relation.sourceId);
      const targetNode = getNodeTypeById(plugin, relation.destinationId);
      const relationType = findRelationTypeById(relation.relationshipTypeId);

      if (sourceNode && targetNode && relationType) {
        message = `Are you sure you want to delete the relation between "${sourceNode.name}" and "${targetNode.name}" (${relationType.label})?`;
      }
    }

    const modal = new ConfirmationModal(plugin.app, {
      title: "Delete relation",
      message,
      onConfirm: () => handleDeleteRelation(index),
    });
    modal.open();
  };

  const handleAcceptRelation = async (index: number): Promise<void> => {
    const updatedRelations = [...discourseRelations];
    const relation = updatedRelations[index];
    if (!relation) return;
    updatedRelations[index] = { ...relation, status: "accepted" };

    // Cascade: also accept the relation type if it is still provisional
    const updatedRelationTypes = [...plugin.settings.relationTypes];
    const relTypeIndex = updatedRelationTypes.findIndex(
      (rt) => rt.id === relation.relationshipTypeId,
    );
    if (
      relTypeIndex >= 0 &&
      isProvisionalSchema(updatedRelationTypes[relTypeIndex]!)
    ) {
      updatedRelationTypes[relTypeIndex] = {
        ...updatedRelationTypes[relTypeIndex]!,
        status: "accepted",
      };
      plugin.settings.relationTypes = updatedRelationTypes;
    }

    setDiscourseRelations(updatedRelations);
    plugin.settings.discourseRelations = updatedRelations;
    await plugin.saveSettings();
  };

  const handleDeleteRelation = async (index: number): Promise<void> => {
    const updatedRelations = discourseRelations.filter((_, i) => i !== index);
    setDiscourseRelations(updatedRelations);
    plugin.settings.discourseRelations = updatedRelations;
    await plugin.saveSettings();
    new Notice("Relation deleted");
  };

  const localRelations = discourseRelations.filter(
    (relation) => !relation.importedFromRid,
  );
  const importedRelations = discourseRelations.filter(
    (relation) => relation.importedFromRid,
  );

  const renderRelationItem = (relation: DiscourseRelation, index: number) => {
    const importInfo = getImportInfo(relation.importedFromRid);
    const isImported = importInfo.isImported;
    const isProvisional = isProvisionalSchema(relation);
    const spaceName = importInfo.spaceUri
      ? formatImportSource(importInfo.spaceUri, plugin.settings.spaceNames)
      : "imported space";
    const error = errors[index];

    // Imported rows render disabled selects, which cannot be opened to reveal a
    // truncated label, so expose the full value on hover instead.
    const relationType = findRelationTypeById(relation.relationshipTypeId);
    const relationTypeLabel = relationType
      ? `${relationType.label} / ${relationType.complement}`
      : undefined;
    const sourceName = getNodeTypeById(plugin, relation.sourceId)?.name;
    const destinationName = getNodeTypeById(
      plugin,
      relation.destinationId,
    )?.name;

    return (
      <div key={index} className="setting-item">
        <div className="flex min-w-0 flex-1 flex-col gap-1">
          <div className="flex flex-wrap items-center gap-2">
            <select
              value={relation.sourceId}
              onChange={(e) =>
                handleRelationChange(index, "sourceId", e.target.value)
              }
              className={`min-w-24 flex-1 pl-2 ${error ? "input-error" : ""}`}
              disabled={isImported}
              title={sourceName}
            >
              <option value="">Source Node Type</option>
              {plugin.settings.nodeTypes.map((nodeType) => (
                <option key={nodeType.id} value={nodeType.id}>
                  {nodeType.name}
                </option>
              ))}
            </select>

            <select
              value={relation.relationshipTypeId}
              onChange={(e) =>
                handleRelationChange(
                  index,
                  "relationshipTypeId",
                  e.target.value,
                )
              }
              className={`min-w-56 flex-[3] pl-2 ${error ? "input-error" : ""}`}
              disabled={isImported}
              title={relationTypeLabel}
            >
              <option value="">Relation Type</option>
              {(isImported
                ? plugin.settings.relationTypes
                : plugin.settings.relationTypes.filter(isAcceptedSchema)
              ).map((relType) => (
                <option key={relType.id} value={relType.id}>
                  {relType.label} / {relType.complement}
                </option>
              ))}
            </select>

            <select
              value={relation.destinationId}
              onChange={(e) =>
                handleRelationChange(index, "destinationId", e.target.value)
              }
              className={`min-w-24 flex-1 pl-2 ${error ? "input-error" : ""}`}
              disabled={isImported}
              title={destinationName}
            >
              <option value="">Target Node Type</option>
              {plugin.settings.nodeTypes.map((nodeType) => (
                <option key={nodeType.id} value={nodeType.id}>
                  {nodeType.name}
                </option>
              ))}
            </select>

            <div className="flex shrink-0 gap-2">
              {isImported && isProvisional && (
                <button
                  onClick={() => void handleAcceptRelation(index)}
                  className="p-2"
                  title={`Accept this relation triplet from ${spaceName} to create instances of this relation`}
                >
                  Accept
                </button>
              )}
              <button
                onClick={() => confirmDeleteRelation(index)}
                className="mod-warning p-2"
              >
                Delete
              </button>
            </div>
          </div>
          {error && <div className="text-error text-xs">{error}</div>}
          {isImported && (
            <ImportedSchemaMeta
              isProvisional={isProvisional}
              spaceUri={importInfo.spaceUri}
              authorId={relation.authorId}
            />
          )}
        </div>
      </div>
    );
  };

  return (
    <div className="discourse-relations">
      {plugin.settings.nodeTypes.length === 0 ? (
        <div>You need to create some node types first.</div>
      ) : plugin.settings.relationTypes.length === 0 ? (
        <div>You need to create some relation types first.</div>
      ) : (
        <>
          {localRelations.length > 0 && (
            <div>
              <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
                Local
              </h4>
              {localRelations.map((relation) => {
                const index = discourseRelations.indexOf(relation);
                return renderRelationItem(relation, index);
              })}
            </div>
          )}

          {importedRelations.length > 0 && (
            <div className="border-modifier-border mt-6 border-t pt-4">
              <h4 className="text-muted mb-2 text-sm font-semibold uppercase tracking-wide">
                Imported
              </h4>
              {importedRelations.map((relation) => {
                const index = discourseRelations.indexOf(relation);
                return renderRelationItem(relation, index);
              })}
            </div>
          )}

          <div className="mt-4 flex gap-2">
            <button onClick={handleAddRelation} className="p-2">
              Add relation
            </button>
          </div>
        </>
      )}
    </div>
  );
};

