    await cleanSettings(ctx, { relTypes: ["sup", "opp"], rels: [["E", "sup", "C"], ["E", "opp", "C"]] });
    await reopen();
    await tab(ctx, "Relation types");
    await ctx.client.evaluate(`[...${C}.querySelectorAll("button")].find((b) => b.textContent.trim() === "Add relation type").click(); return true;`);
