    await sleep(300);
    await ctx.client.evaluate(`const rows = ${C}.querySelectorAll(".discourse-relation-types .setting-item"); const last = rows[rows.length - 1];
      [...last.querySelectorAll(".relative.min-w-32 > div button")].find((b) => b.textContent.trim() === "Grey")?.click(); return true;`);
    await sleep(300);
    await ctx.client.evaluate(`const i = ${C}.querySelectorAll(".discourse-relation-types input[type=text]")[5]; i.focus(); return true;`);
    out.push(await shoot(ctx, "relation-types-add.png", { toSel: ".discourse-relation-types > div.mt-4", pad: 16 }));

    // 2. Discourse relations list
    await cleanSettings(ctx, { relTypes: ["sup", "opp", "inf"], rels: [["E", "sup", "C"], ["E", "opp", "C"], ["E", "inf", "Q"], ["S", "inf", "E"]] });
    await reopen();
    await tab(ctx, "Discourse relations");
    out.push(await shoot(ctx, "discourse-relations-settings.png", { toSel: ".discourse-relations div.mt-4", pad: 16 }));

    // 3. Adding Claim -> supports -> Question
    await ctx.client.evaluate(`[...${C}.querySelectorAll("button")].find((b) => b.textContent.trim() === "Add relation").click(); return true;`);
    await sleep(300);
    const sel = ".discourse-relations select";
    const n = await ctx.client.evaluate(`return ${C}.querySelectorAll(${ctx.json(sel)}).length;`);
    await setInput(ctx, sel, n - 3, ids.C);
    await setInput(ctx, sel, n - 2, ids.sup);
    await sleep(200);
    out.push(await shoot(ctx, "discourse-relations-add-partial.png", { toSel: ".discourse-relations div.mt-4", pad: 16 }));
    await setInput(ctx, sel, n - 1, ids.Q);
    await sleep(200);
    out.push(await shoot(ctx, "discourse-relations-add.png", { toSel: ".discourse-relations div.mt-4", pad: 16 }));

    // 4. Key image toggle on Evidence
    await cleanSettings(ctx, { relTypes: ["sup", "opp", "inf"], rels: [["E", "sup", "C"]] });
    await reopen();
    await tab(ctx, "Node types");
    await ctx.client.evaluate(`[...${C}.querySelectorAll(".node-type-item")].find((el) => el.textContent.includes("Evidence")).click(); return true;`);
    await sleep(500);
    const ki = await ctx.client.evaluate(`const it = [...${C}.querySelectorAll(".setting-item")].find((s) => s.textContent.includes("Key image")); return it ? { on: it.querySelector(".checkbox-container")?.classList.contains("is-enabled"), text: it.innerText } : null;`);
    out.push({ ki });
    out.push(await shoot(ctx, "key-figure.png", {}));
    await ctx.client.evaluate(`app.setting.close(); return true;`);
    return out;
  },
  expect: (a) => ({ pass: true, actual: JSON.stringify(a) }),
  teardown: async (ctx, state) => {
    await ctx.client.evaluate(`app.setting.close(); return true;`);
    await ctx.client.evaluate(`const p = ${P(ctx)}; const s = JSON.parse(${ctx.json(state.settings)}); for (const k of Object.keys(p.settings)) delete p.settings[k]; Object.assign(p.settings, s); return p.saveSettings().then(() => true);`);
    const after = await ctx.client.evaluate(`return app.vault.adapter.read(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")});`);
    if (after !== state.disk) {
      await ctx.client.evaluate(`return app.vault.adapter.write(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")}, ${ctx.json(state.disk)}).then(() => true);`);
      fs.writeFileSync(OUT + "teardown-note.txt", "data.json differed after saveSettings; rewrote original bytes\n");
    }
  },
};
